cat package.json | grep -A12 '"scripts"'; ls test test/markdown-it | head -40; cat > /tmp/t.mjs <<'EOF'
import MarkdownIt from './src/index.ts'
for (const p of ['default','commonmark','zero']) { const md = new MarkdownIt(p); if(p==='zero') md.enable(['backticks','link','image']);
for (const s of ['[foo `bar` baz`','![alt `code` x`','[`a`b`','[``a``b`c``','[`a`](x) `b` c`','`a` [x ``b`` `` ` c']) console.log(p, JSON.stringify(s), md.render(s).trim()) }
EOF
cp /tmp/t.mjs ./_t.mjs && node _t.mjs; rm _t.mjs

